with rece_all as( select sum(prp.AMOUNT + (select nvl(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = #{rec_type_02} and lixi.REC_TYPE =#{rec_type_03})) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate from PTL_RECE_POSITION prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = prp.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01'
#{instCode,jdbcType=VARCHAR}
where prp.HODING_TYPE =#{position_type_03} and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and prp.REC_TYPE in (#{rec_type_01}, #{rec_type_02}) group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID ), rece_all_jz as( select sum(prp.AMOUNT + (select nvl(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = #{rec_type_02} and lixi.REC_TYPE =#{rec_type_03})) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate from PTL_RECE_POSITION_FLOW prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = pp.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01'
#{instCode,jdbcType=VARCHAR}
where prp.HODING_TYPE =#{position_type_03} and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and prp.REC_TYPE in (#{rec_type_01}, #{rec_type_02}) and prp.INPUT_TYPE = '04' group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID ) select cc.*,
decode(cc.finprodType2,'F01',secAcctId,cc.finprodId) assetId,
(select listagg(to_char(fcp.mdate, 'yyyy-mm-dd'), ',') within group( order by fcp.branch) from FIN_CASH_info fci inner join FIN_CASH_PLAN fcp on fci.cash_id = fcp.cash_id and fci.finprod_id = fcp.finprod_id and fci.branch = fcp.branch where fci.finprod_id = cc.finprodId and fci.cash_type_2 = 'C19' and instr(cc.branchAll,fcp.branch)>0) fxmdateStr
from ( select sum(dd.theoryAmount) theoryAmt, sum(dd.realityAmount) fpriceAmt, sum(dd.theoryCapital) theoryPrin, sum(dd.theoryInterest) theoryInt, sum(dd.penalty) theoryPenaltyInt, sum(dd.realityPenalty) penaltyIntamt, listagg(dd.cashType, ',') within group ( order by dd.branch) cashType, listagg(dd.branchType, ',') within group ( order by dd.branch) branchType, listagg(dd.branch, ',') within group ( order by dd.branch) branchAll, listagg(dd.isAccrPenaltyInt1, ',') within group ( order by dd.branch) isAccrPenaltyInt, listagg(dd.penaltyBaseType1, ',') within group ( order by dd.branch) penaltyBaseType, listagg(dd.fxYield1, ',') within group ( order by dd.branch) fxYield, listagg(dd.isRushBack1, ',') within group ( order by dd.branch) isRushBack, dd.finprodId, dd.finprodMarketId, dd.finprodName, min(dd.vdate) vdate, dd.mdate, dd.endPayDate, dd.finprodType2, dd.finprodTypeName, to_char(min(dd.vdate), 'yyyy-mm-dd') vdateStr, to_char(dd.mdate, 'yyyy-mm-dd') mdateStr, dd.secAcctId, dd.secAcctName secManageAcctName, dd.chIldName from ( select fcp.CASH_TYPE cashType, fp.FINPROD_ID finprodId, fp.finprod_market_id finprodMarketId, fpty.TYPE_8 finprodType2, (select item_value from sys_datadict_list where item_code=fpty.TYPE_8 and dict_code='PINAN_ASSET_TYPE' ) finprodTypeName, nvl(fp.FINPROD_ABBR,fp.FINPROD_NAME) finprodName, ftp.VDATE vdate, ftp.MDATE mdate, nvl(bb.amount,0) theoryAmount, nvl(bb.amount -aa.amount,0) realityAmount, case when ftp.BRANCH_TYPE =#{BRANCH_TYPE_D01} then aa.amount else 0 end theoryCapital, case when ftp.BRANCH_TYPE =#{BRANCH_TYPE_D02} then aa.amount else 0 end theoryInterest, (select max(SETTLE_DATE) from TRD_FIN_PRODUCT_DEAL_TOTAL where FINPROD_ID = ftp.FINPROD_ID and MDATE = ftp.MDATE AND p_trade_id is null and is_cancel='N' and IS_OVERDUE_DEAL ='Y' and (decode(SEC_MANAGE_ACCT_ID,null,'999999',SEC_MANAGE_ACCT_ID)=aa.secAcctId or decode(CHL_ID,null,'999999',CHL_ID)=aa.secAcctId) and PS in (#{PS_T09},#{PS_T08},#{PS_T07},#{PS_T54})) endPayDate, nvl(receival.intTotAmt,0) * nvl(bb.amount,0) / (select sum(rece_amt + ( select nvl(sum(rece_amt), 0) from PTL_SEC_RECEIVABLES psrr inner join PTL_PORTFOLIO pp on psrr.PORTFOLIO_ID = pp.PORTFOLIO_ID
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = psrr.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01'
#{instCode,jdbcType=VARCHAR}
where psrr.branch in (select without_branch from VW_REPAY_WITHOUT_INT where branch = psr.branch and FINPRODID = psr.finprod_id) and psrr.portfolio_id = psr.portfolio_id and psrr.finprod_id = psr.FINPROD_ID and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psrr.CDATE = ftp.mdate)) from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = psr.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01'
#{instCode,jdbcType=VARCHAR}
where psr.FINPROD_ID = ftp.finprod_id and psr.branch = ftp.branch and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psr.CDATE = ftp.mdate) penalty, (select sum(tdta.PENALTY_INTAMT) from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join TRD_DEAL_TOTAL_ADD tdta on tfpdt.TOTLE_TRADE_ID = tdta.TOTLE_TRADE_ID WHERE tfpdt.PS in (#{PS_T09},#{PS_T08},#{PS_T07},#{PS_T54}) and tdta.MP_FINPROD_ID is null and tfpdt.p_totle_trade_id is null AND tfpdt.TRADE_STATUS ='01' AND tfpdt.IS_CANCEL = 'N' and tfpdt.is_overdue_deal='Y' and (tfpdt.is_clean='N' OR tfpdt.is_clean IS NULL) AND tfpdt.FINPROD_ID = aa.finprodId and tfpdt.branch = aa.branch and (tfpdt.SEC_MANAGE_ACCT_ID = decode(aa.secAcctId,null,'999999',aa.secAcctId) or tfpdt.CHL_ID = decode(aa.secAcctId,null,'999999',aa.secAcctId))
) realityPenalty, ftpa.IS_ACCR_PENALTY_INT isAccrPenaltyInt1, ftpa.PENALTY_BASE_TYPE penaltyBaseType1, ftp.IS_RUSH_BACK isRushBack1, fccr.YIELD * 100 fxYield1, ftp.BRANCH branch, ftp.BRANCH_TYPE branchType, aa.secAcctId secAcctId, (select sec_acct_name from STL_SEC_ACCT_INFO where sec_acct_id= aa.secAcctId) secAcctName, (SELECT NVL(A.FINPROD_ABBR, A.FINPROD_NAME) FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID where A.FINPROD_ID = aa.secAcctId) chIldName from rece_all aa inner join FIN_TRADE_PRODUCT ftp on ftp.FINPROD_ID = aa.finprodId and ftp.BRANCH = aa.branch left join FIN_TRADE_PRODUCT_ADD ftpa ON ftpa.FINPROD_ID = ftp.FINPROD_ID and ftpa.BRANCH = aa.branch left join FIN_CASH_INFO fci on fci.FINPROD_ID = ftp.FINPROD_ID and fci.CASH_TYPE_2= decode(ftp.BRANCH_TYPE,#{BRANCH_TYPE_D01},#{CASH_TYPE_2_C01},#{BRANCH_TYPE_D02},#{CASH_TYPE_2_C02}) and fci.BRANCH=0 left join FIN_CASH_PLAN fcp on fcp.CASH_ID = fci.CASH_ID and ftp.MDATE = fcp.MDATE left join rece_all_jz bb on ftp.FINPROD_ID = bb.finprodId and ftp.BRANCH = bb.branch and bb.cdate = case when bb.payDate>ftp.mdate then bb.payDate+1 else ftp.mdate+1 end and bb.secAcctId = aa.secAcctId INNER join FIN_PRODUCT fp on fp.FINPROD_ID = aa.finprodId left join FIN_PRODUCT_TYPE fpty on fpty.FINPROD_ID = aa.finprodId and fpty.BRANCH = 0 left join FIN_CASH_CALC_RULE fccr on fccr.FINPROD_ID = ftp.FINPROD_ID and fccr.BRANCH = ftp.BRANCH and fccr.IS_INITIAL = 'Y' left join (select sum(psr.PENALTY_INT_AMT) intAmt, sum(psr.PENALTY_INT_TOT_AMT) intTotAmt, psr.FINPROD_ID, nvl(pni.BRANCH,psr.branch) branch from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID inner join FIN_TRADE_PRODUCT ftp on ftp.finprod_id = psr.finprod_id and ftp.branch = psr.branch left join VW_REPAY_WITHOUT_INT pni on psr.branch = pni.WITHOUT_BRANCH and psr.FINPROD_ID = pni.finprodId where cdate = #{sysDate} - 1 and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' group by psr.FINPROD_ID, nvl(pni.BRANCH,psr.branch)) receival on receival.FINPROD_ID = aa.finprodId and receival.branch =aa.branch
aa.cdate = #{sysDate} and aa.payDate < #{sysDate}
AND fpty.TYPE_8 IN(
#{item}
)
and ftp.FINPROD_ID like CONCAT('%', CONCAT(#{finprodMarketId}, '%'))
AND fcp.CASH_TYPE IN(
#{item}
)
AND ftp.MDATE >= to_date(#{registDateStart}, 'yyyy-MM-dd')
AND ftp.MDATE <= to_date(#{registDateEnd}, 'yyyy-MM-dd')
) dd group by dd.finprodId, dd.finprodMarketId, dd.finprodName, dd.mdate, dd.endPayDate, dd.finprodType2, dd.finprodTypeName ,dd.secAcctId ,dd.secAcctName ,dd.chIldName order by dd.finprodType2,dd.finprodId,dd.mdate ) cc
left join TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt on tfpdt.finprod_id = cc.finprodId and tfpdt.branch != 0 and instr(cc.branchAll,tfpdt.branch)>0 and (cc.secAcctId=decode(tfpdt.sec_manage_acct_id,null,'999999',tfpdt.sec_manage_acct_id) or cc.secAcctId=decode(tfpdt.chl_id,null,'999999',tfpdt.chl_id) ) AND tfpdt.Is_Cancel='N' AND tfpdt.p_trade_id is null and tfpdt.Is_Clean='Y' and tfpdt.p_totle_trade_id is null
WHERE tfpdt.totle_trade_id is null

with rece_all_jz as( select sum(prp.AMOUNT + (select nvl(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = #{rec_type_02} and lixi.REC_TYPE =#{rec_type_03})) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.PAY_DATE payDate, prp.CDATE cdate from PTL_RECE_POSITION_FLOW prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID
INNER JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = prp.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01' AND dani.INSTITUTION_CODE IN
#{item}
where prp.HODING_TYPE =#{position_type_03} and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and prp.REC_TYPE in (#{rec_type_01}, #{rec_type_02}) and prp.INPUT_TYPE = '04' group by prp.FINPROD_ID, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID ) select fcp.CASH_TYPE cashType, fpty.TYPE_8 finprodType2, (select item_value from sys_datadict_list where item_code=fpty.TYPE_8 and dict_code='PINAN_ASSET_TYPE' ) finprodTypeName, fp.FINPROD_ID finprodId, fp.finprod_market_id finprodMarketId, nvl(fp.FINPROD_ABBR,fp.FINPROD_NAME) finprodName, (select min(vdate) from FIN_TRADE_PRODUCT where FINPROD_ID = ftp.FINPROD_ID and branch in (ftp.branch,ftp2.branch)) vdate, to_char((select min(vdate) from FIN_TRADE_PRODUCT where FINPROD_ID = ftp.FINPROD_ID and branch in (ftp.branch,ftp2.branch)), 'yyyy-mm-dd') vdateStr, ftp.MDATE mdate, to_char(ftp.MDATE,'yyyy-mm-dd') mdateStr, aa.endPayDate endPayDate, nvl(bb.amount,0) theoryAmt, nvl(aa.realityAmount,0) fpriceAmt, (SELECT NVL(SUM(PENALTY_INT_TOT_AMT),0) FROM PTL_SEC_RECEIVABLES psr INNER JOIN PTL_PORTFOLIO pp ON psr.PORTFOLIO_ID = pp.PORTFOLIO_ID LEFT JOIN VW_REPAY_WITHOUT_INT pni ON pni.BRANCH = psr.branch AND psr.FINPROD_ID = pni.finprodId
INNER JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = psr.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01' AND dani.INSTITUTION_CODE IN
#{item}
WHERE psr.FINPROD_ID = ftp.finprod_id AND psr.branch = ftp.branch AND NVL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' AND psr.CDATE = aa.endPayDate-1 ) * NVL(bb.amount,0)/ (select sum(rece_amt + ( select nvl(sum(rece_amt), 0) from PTL_SEC_RECEIVABLES psrr inner join PTL_PORTFOLIO pp on psrr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psrr.branch in (select without_branch from VW_REPAY_WITHOUT_INT where branch = psr.branch and FINPRODID = psr.finprod_id) and psrr.portfolio_id = psr.portfolio_id and psrr.finprod_id = psr.FINPROD_ID and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psrr.CDATE = ftp.mdate)) from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID
INNER JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = psr.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01' AND dani.INSTITUTION_CODE IN
#{item}
where psr.FINPROD_ID = ftp.finprod_id and psr.branch = ftp.branch and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psr.CDATE = ftp.mdate) theoryPenaltyInt, nvl(aa.realityPenalty,0) penaltyIntamt, ftp.IS_RUSH_BACK isRushBack, decode(ftp.BRANCH_TYPE,'D01',ftp.BRANCH,ftp2.BRANCH) bjBranch, decode(ftp.BRANCH_TYPE,'D02',ftp.BRANCH,ftp2.BRANCH) liBranch, ftp.BRANCH_TYPE, nvl(aa.secAcctId,aa.chlId) secAcctId, (select sec_acct_name from STL_SEC_ACCT_INFO where sec_acct_id= aa.secAcctId) secManageAcctName, (SELECT NVL(A.FINPROD_ABBR, A.FINPROD_NAME) FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID where A.FINPROD_ID = aa.chlId) chIldName
,SI.INSTITUTION_NAME institutionName
from (select sum(tfpdt.FPRICE_AMT) realityAmount, sum(tdta.PENALTY_INTAMT) realityPenalty, tfpdt.BRANCH branch, tfpdt.FINPROD_ID finprodId, tfpdt.mDate mdate, tfpdt.SEC_MANAGE_ACCT_ID secAcctId, tfpdt.CHL_ID chlId, max(SETTLE_DATE) endPayDate
,tfpdt.INSTITUTION_CODE institutionCode
