,tfpdt.INSTITUTION_CODE
) aa inner join FIN_TRADE_PRODUCT ftp on ftp.FINPROD_ID = aa.finprodId and ftp.BRANCH = aa.branch left join FIN_CASH_INFO fci on fci.FINPROD_ID = ftp.FINPROD_ID and fci.CASH_TYPE_2 = decode(ftp.BRANCH_TYPE,#{BRANCH_TYPE_D01},#{CASH_TYPE_2_C01},#{BRANCH_TYPE_D02},#{CASH_TYPE_2_C02}) and fci.BRANCH=0 left join FIN_CASH_PLAN fcp on fcp.CASH_ID = fci.CASH_ID and ftp.MDATE = fcp.MDATE left join FIN_PRODUCT fp on fp.FINPROD_ID = aa.finprodId left join FIN_PRODUCT_TYPE fpty on fpty.FINPROD_ID = aa.finprodId and fpty.BRANCH = 0 left join rece_all_jz bb on ftp.FINPROD_ID = bb.finprodId and bb.payDate = fcp.PAY_DATE and bb.cdate= case when bb.payDate>ftp.mdate then bb.payDate+1 else ftp.mdate+1 end and (bb.secAcctId = decode(aa.secAcctId,null,'999999',aa.secAcctId) or bb.secAcctId = decode(aa.chlId,null,'999999',aa.chlId)) left join FIN_TRADE_PRODUCT ftp2 on ftp.FINPROD_ID = ftp2.FINPROD_ID and ftp.BRANCH != ftp2.branch and ftp.mdate = ftp2.mdate
