order by fp.FINPROD_TYPE2,ftp.FINPROD_ID,ftp.mdate

with rece_all as( select sum(prp.AMOUNT + (select nvl(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = '02' and lixi.REC_TYPE = '03')) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate, prp.PORTFOLIO_ID portfolioId from PTL_RECE_POSITION prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = prp.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01'
#{instCode,jdbcType=VARCHAR}
where prp.HODING_TYPE = '03' and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID, prp.PORTFOLIO_ID ), rece_all_jz as( select sum(prp.AMOUNT + (select nvl(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = '02' and lixi.REC_TYPE ='03')) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate, prp.PORTFOLIO_ID portfolioId from PTL_RECE_POSITION_FLOW prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = prp.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01'
#{instCode,jdbcType=VARCHAR}
where prp.HODING_TYPE =#{position_type_03} and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and prp.REC_TYPE in ('01', '02') and prp.INPUT_TYPE = '04' group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID, prp.PORTFOLIO_ID )
select dd.finprodId, (select listagg(PORTFOLIO_ID, ',') within group ( order by VDATE) from PTL_PORTFOLIO where PARENT_PORTFOLIO_ID =dd.portfolioId) childPortfolioIds, dd.portfolioId,dd.portfolioName, SUM(dd.theoryAmount) theoryAmt, SUM(dd.realityAmount) fpriceAmt, sum(dd.theoryCapital) theoryPrin, sum(dd.theoryInterest) theoryInt, sum(dd.penalty) theoryPenaltyInt, sum(dd.realityPenalty) penaltyIntamt
,dani.belong_institution_code belongInstitutionCode
from ( select ftp.FINPROD_ID finprodId, aa.portfolioId, (select portfolio_name from ptl_portfolio where portfolio_id = aa.portfolioId) portfolioName, nvl(bb.amount,0) theoryAmount, nvl(bb.amount -aa.amount,0) realityAmount, case when ftp.BRANCH_TYPE ='D01' then aa.amount else 0 end theoryCapital, case when ftp.BRANCH_TYPE ='D02' then aa.amount else 0 end theoryInterest, nvl(receival.intTotAmt,0) * nvl(bb.amount,0) / (select sum(rece_amt + ( select nvl(sum(rece_amt), 0) from PTL_SEC_RECEIVABLES psrr inner join PTL_PORTFOLIO pp on psrr.PORTFOLIO_ID = pp.PORTFOLIO_ID
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = psrr.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01'
#{instCode,jdbcType=VARCHAR}
where psrr.branch in (select without_branch from VW_REPAY_WITHOUT_INT where branch = psr.branch and FINPRODID = psr.finprod_id) and psrr.PORTFOLIO_ID =aa.portfolioid and psrr.portfolio_id = psr.portfolio_id and psrr.finprod_id = psr.FINPROD_ID and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psrr.CDATE = ftp.mdate)) from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psr.FINPROD_ID = ftp.finprod_id and psr.PORTFOLIO_ID =aa.portfolioid and psr.branch = ftp.branch and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psr.CDATE = ftp.mdate) penalty, (select sum(tdta.PENALTY_INTAMT) from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt inner join PTL_PORTFOLIO pp on tfpdt.PORTFOLIO_ID = pp.PORTFOLIO_ID left join TRD_DEAL_TOTAL_ADD tdta on tfpdt.TOTLE_TRADE_ID = tdta.TOTLE_TRADE_ID WHERE tfpdt.PS in ('T09','T08','T07','T54') and tdta.MP_FINPROD_ID is null AND tfpdt.TRADE_STATUS ='01' AND tfpdt.IS_CANCEL = 'N' and tfpdt.is_overdue_deal='Y' and (tfpdt.is_clean='N' OR tfpdt.is_clean IS NULL) AND tfpdt.FINPROD_ID = aa.finprodId and tfpdt.branch = aa.branch and tfpdt.PORTFOLIO_ID = aa.portfolioId and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and (tfpdt.SEC_MANAGE_ACCT_ID = decode(aa.secAcctId,null,'999999',aa.secAcctId) or tfpdt.CHL_ID = decode(aa.secAcctId,null,'999999',aa.secAcctId))
) realityPenalty from rece_all aa inner join FIN_TRADE_PRODUCT ftp on ftp.FINPROD_ID = aa.finprodId and ftp.BRANCH = aa.branch left join rece_all_jz bb on ftp.FINPROD_ID = bb.finprodId and ftp.BRANCH = bb.branch and bb.cdate= case when bb.payDate>ftp.mdate then bb.payDate+1 else ftp.mdate+1 end and bb.secAcctId = aa.secAcctId and bb.portfolioId = aa.portfolioId left join (select sum(psr.PENALTY_INT_AMT) intAmt, sum(psr.PENALTY_INT_TOT_AMT) intTotAmt, psr.FINPROD_ID, nvl(pni.BRANCH,psr.branch) branch, psr.PORTFOLIO_ID from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID inner join FIN_TRADE_PRODUCT ftp on ftp.finprod_id = psr.finprod_id and ftp.branch = psr.branch left join VW_REPAY_WITHOUT_INT pni on psr.branch = pni.WITHOUT_BRANCH and psr.FINPROD_ID = pni.finprodId
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = psr.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01'
#{instCode,jdbcType=VARCHAR}
where cdate = #{sysDate} - 1 and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' group by psr.FINPROD_ID, nvl(pni.BRANCH,psr.branch),psr.PORTFOLIO_ID) receival on receival.FINPROD_ID = aa.finprodId and receival.branch =aa.branch and receival.PORTFOLIO_ID = aa.portfolioId
aa.cdate = #{sysDate} and aa.payDate < #{sysDate}
and aa.finprodId = #{finprodId}
AND aa.branch IN
${item}
and aa.secAcctId = #{secAcctId}
) dd
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = dd.portfolioId AND dani.model_type ='02' AND dani.data_type ='PTL01'
group by dd.finprodId,dd.portfolioId,dd.portfolioName
,dani.belong_institution_code

with rece_all as( select sum(prp.AMOUNT + (select nvl(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = '02' and lixi.REC_TYPE = '03')) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate, prp.PORTFOLIO_ID portfolioId from PTL_RECE_POSITION prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = prp.PORTFOLIO_ID AND dani.INSTITUTION_CODE=#{institutionCode}
where prp.HODING_TYPE = '03'
and pp.PARENT_PORTFOLIO_ID = #{portfolioId}
group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID, prp.PORTFOLIO_ID ), rece_all_jz as( select sum(prp.AMOUNT + (select nvl(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = '02' and lixi.REC_TYPE ='03')) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate, prp.PORTFOLIO_ID portfolioId from PTL_RECE_POSITION_FLOW prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = prp.PORTFOLIO_ID AND dani.INSTITUTION_CODE=#{institutionCode}
where prp.HODING_TYPE =#{position_type_03}
and pp.PARENT_PORTFOLIO_ID = #{portfolioId}
and prp.REC_TYPE in ('01', '02') and prp.INPUT_TYPE = '04' group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID, prp.PORTFOLIO_ID )
select dd.finprodId, dd.portfolioId, dd.portfolioName, SUM(dd.theoryAmount) theoryAmt, SUM(dd.realityAmount) fpriceAmt, sum(dd.theoryCapital) theoryPrin, sum(dd.theoryInterest) theoryInt, sum(dd.penalty) theoryPenaltyInt, sum(dd.realityPenalty) penaltyIntamt from ( select ftp.FINPROD_ID finprodId, aa.portfolioId, (select portfolio_name from ptl_portfolio where portfolio_id = aa.portfolioId) portfolioName, nvl(bb.amount,0) theoryAmount, nvl(bb.amount -aa.amount,0) realityAmount, case when ftp.BRANCH_TYPE ='D01' then aa.amount else 0 end theoryCapital, case when ftp.BRANCH_TYPE ='D02' then aa.amount else 0 end theoryInterest, nvl(receival.intTotAmt,0) * nvl(bb.amount,0) / (select sum(rece_amt + ( select nvl(sum(rece_amt), 0) from PTL_SEC_RECEIVABLES psrr inner join PTL_PORTFOLIO pp on psrr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psrr.branch in (select without_branch from VW_REPAY_WITHOUT_INT where branch = psr.branch and FINPRODID = psr.finprod_id) and psrr.PORTFOLIO_ID =aa.portfolioid and psrr.portfolio_id = psr.portfolio_id and psrr.finprod_id = psr.FINPROD_ID
and pp.PARENT_PORTFOLIO_ID = #{portfolioId}
and psrr.CDATE = ftp.mdate)) from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psr.FINPROD_ID = ftp.finprod_id and psr.PORTFOLIO_ID =aa.portfolioid and psr.branch = ftp.branch
and pp.PARENT_PORTFOLIO_ID = #{portfolioId}
and psr.CDATE = ftp.mdate) penalty, sffx.sffxje realityPenalty from rece_all aa inner join FIN_TRADE_PRODUCT ftp on ftp.FINPROD_ID = aa.finprodId and ftp.BRANCH = aa.branch left join rece_all_jz bb on ftp.FINPROD_ID = bb.finprodId and ftp.BRANCH = bb.branch and bb.cdate= case when bb.payDate>ftp.mdate then bb.payDate+1 else ftp.mdate+1 end and bb.secAcctId = aa.secAcctId and bb.portfolioId = aa.portfolioId left join (select sum(psr.PENALTY_INT_AMT) intAmt, sum(psr.PENALTY_INT_TOT_AMT) intTotAmt, psr.FINPROD_ID, nvl(pni.BRANCH,psr.branch) branch, psr.PORTFOLIO_ID from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID inner join FIN_TRADE_PRODUCT ftp on ftp.finprod_id = psr.finprod_id and ftp.branch = psr.branch left join VW_REPAY_WITHOUT_INT pni on psr.branch = pni.WITHOUT_BRANCH and psr.FINPROD_ID = pni.finprodId where cdate = #{sysDate} - 1
and pp.PARENT_PORTFOLIO_ID = #{portfolioId}
group by psr.FINPROD_ID, nvl(pni.BRANCH,psr.branch),psr.PORTFOLIO_ID) receival on receival.FINPROD_ID = aa.finprodId and receival.branch =aa.branch and receival.PORTFOLIO_ID = aa.portfolioId left join (select TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID, TRD_PRODUCT_DEAL.FINPROD_ID, TRD_PRODUCT_DEAL.CHL_ID, TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, TRD_PRODUCT_DEAL.BRANCH, sum(decode(TRD_PRODUCT_DEAL.PS,#{PS_T01},TRD_PRODUCT_DEAL.TRADE_AMT*(-1),TRD_PRODUCT_DEAL.TRADE_AMT)) sffxje from TRD_PRODUCT_DEAL left join TRD_PRODUCT_DEAL_ADD on TRD_PRODUCT_DEAL.TRADE_ID = TRD_PRODUCT_DEAL_ADD.TRADE_ID where TRD_PRODUCT_DEAL.BUSI_TYPE= #{BUSI_TYPE_37} and TRD_PRODUCT_DEAL.TRADE_STATUS= #{TRADE_STATUS_01} and TRD_PRODUCT_DEAL.IS_CANCEL= #{YES_OR_NO_N} and TRD_PRODUCT_DEAL.TRADE_DATE= #{sysDate} group by TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID, TRD_PRODUCT_DEAL.FINPROD_ID, TRD_PRODUCT_DEAL.CHL_ID, TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, TRD_PRODUCT_DEAL.BRANCH ) sffx on aa.finprodId = sffx.FINPROD_ID and aa.BRANCH = sffx.BRANCH and aa.portfolioId = sffx.PORTFOLIO_ID and (nvl(nvl(sffx.CHL_ID,sffx.SEC_MANAGE_ACCT_ID),'999999')=aa.secAcctId)
aa.cdate = #{sysDate} and aa.payDate < #{sysDate}
and aa.finprodId = #{finprodId}
AND aa.branch IN
${item}
and aa.secAcctId = #{secAcctId}
) dd group by dd.finprodId,dd.portfolioId,dd.portfolioName

select dd.*
,((select nvl(sum(aa.amount),0) from (select sum(nvl(prp.amount,0)) amount from PTL_RECE_POSITION prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join VW_REPAY_WITHOUT_INT pni on pni.WITHOUT_BRANCH = prp.branch and prp.FINPROD_ID = pni.finprodId
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = prp.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01'
#{instCode,jdbcType=VARCHAR}
prp.FINPROD_ID = #{finprodId}
AND (prp.branch IN
${item}
or prp.branch in (pni.WITHOUT_BRANCH))
and (prp.SEC_ACCT_ID = #{secAcctId})
and prp.HODING_TYPE='03' and prp.CDATE = #{sysDate} and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' group by prp.PORTFOLIO_ID) aa
)+( select nvl(sum(aa.amount),0) from ( select sum(nvl(prp.amount,0)) amount from PTL_RECE_POSITION_FLOW prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join VW_REPAY_WITHOUT_INT pni on pni.WITHOUT_BRANCH = prp.branch and prp.FINPROD_ID = pni.finprodId
inner JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = prp.PORTFOLIO_ID AND dani.model_type ='02' AND dani.data_type ='PTL01'
#{instCode,jdbcType=VARCHAR}
prp.FINPROD_ID = #{finprodId}
AND (prp.branch IN
${item}
or prp.branch in (pni.WITHOUT_BRANCH))
and (prp.SEC_ACCT_ID = #{secAcctId})
and prp.HODING_TYPE='01' and prp.CDATE = #{sysDate} and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' group by prp.PORTFOLIO_ID ) aa
)
+#{theoryPenaltyInt}
) residueAmount
from ( select tfpdt.TOTLE_TRADE_ID totleTradeId, '有效' tradeStatus, tfpdt.SETTLE_DATE settleDate, tfpdt.TRADE_DATE tradeDate, tfpdt.FPRICE_AMT accountingAmt from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join TRD_DEAL_TOTAL_ADD tdta on tfpdt.TOTLE_TRADE_ID = tdta.TOTLE_TRADE_ID
and tfpdt.MDATE =to_date(#{mdate},'yyyy-mm-dd')
and tfpdt.FINPROD_ID = #{finprodId}
and tfpdt.PS in (#{PS_T09},#{PS_T08},#{PS_T07},#{PS_T54})
and (tfpdt.SEC_MANAGE_ACCT_ID = #{secAcctId} or tfpdt.CHL_ID = #{secAcctId})
AND tfpdt.IS_CANCEL = 'N' and tfpdt.TRADE_STATUS ='01' and tdta.MP_FINPROD_ID is null and tfpdt.P_TOTLE_TRADE_ID is null and tfpdt.is_overdue_deal = 'Y'
AND tfpdt.INSTITUTION_CODE IN
#{item}
union all select tfpdt.TOTLE_TRADE_ID totleTradeId, '流程中' tradeStatus, tfpdt.SETTLE_DATE settleDate, tfpdt.TRADE_DATE tradeDate, tfpdt.FPRICE_AMT accountingAmt from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join WFL_TRD_DEAL_TOTAL_ADD tdta on tfpdt.TOTLE_TRADE_ID = tdta.TOTLE_TRADE_ID
and tfpdt.MDATE =to_date(#{mdate},'yyyy-mm-dd')
and tfpdt.FINPROD_ID = #{finprodId}
and tfpdt.PS in (#{PS_T09},#{PS_T08},#{PS_T07},#{PS_T54})
and (tfpdt.SEC_MANAGE_ACCT_ID = #{secAcctId} or tfpdt.CHL_ID = #{secAcctId})
AND tfpdt.IS_CANCEL = 'N' and tfpdt.TRADE_STATUS ='01' and tdta.MP_FINPROD_ID is null and tfpdt.P_TOTLE_TRADE_ID is null and tfpdt.is_overdue_deal = 'Y'
AND tfpdt.INSTITUTION_CODE IN
#{item}
) dd order by dd.tradeDate desc

select /* modify by jiangpeng on 20210430 TISHKBS-2089 运营端-逾期标的信息导入报错 */ /*(select distinct basis from FIN_CASH_CALC_RULE where finprod_id=ftp.finprod_id and branch=0 and EFF_DATE= (select min(vdate) from fin_trade_product WHERE finprod_id =ftp.finprod_id) and basis is not null ) basis,*/ (select distinct rule.BASIS from FIN_CASH_CALC_RULE rule left join FIN_CASH_INFO info on rule.CASH_ID = info.CASH_ID where info.FINPROD_ID = ftp.finprod_id and CASH_TYPE_2 = #{cashType2} and rule.BASIS is not null) basis, listagg(fcp.cash_id, ',') within group ( order by ftp.branch) cashIds, (select item_value from sys_datadict_list where item_code = fpty.TYPE_8 and dict_code = 'PINAN_ASSET_TYPE') finprodTypeName, fpty.TYPE_8 finprodType, ftp.FINPROD_TYPE finprodTypeGz, ftp.FINPROD_TYPE2 finprodTypeTg, ftp.finprod_id finprodId, (select to_char(min(vdate), 'yyyy-mm-dd') from fin_trade_product
and finprod_id = #{finprodId}
and branch in
${item}
) vdateStr, to_char(ftp.mdate,'yyyy-mm-dd') mdateStr, to_char(ftp.mdate,'yyyy-mm-dd') fxvdateStr, to_char(fcp.mdate,'yyyy-mm-dd') fxmdateStr, nvl(fp.FINPROD_ABBR, fp.FINPROD_NAME) finprodName, fccr.yield * 100 fxYield, ftp.IS_RUSH_BACK isRushBack, ftpa.is_accr_penalty_int isAccrPenaltyInt, ftpa.penalty_base_type penaltyBaseType from fin_trade_product ftp INNER join FIN_PRODUCT fp on fp.FINPROD_ID = ftp.finprod_id left join FIN_PRODUCT_TYPE fpty on fpty.FINPROD_ID = ftp.finprod_id and fpty.BRANCH = 0 left join fin_trade_product_add ftpa on ftp.finprod_id = ftpa.finprod_id and ftp.branch = ftpa.branch left join FIN_CASH_CALC_RULE fccr on fccr.finprod_id = ftp.finprod_id and fccr.branch = ftp.branch left join Fin_Cash_Plan fcp on fcp.finprod_id = ftp.finprod_id and fcp.branch = ftp.branch
and ftp.finprod_id = #{finprodId}
and ftp.branch in (${bjBranch},${liBranch})
and ftp.branch=${bjBranch}
and ftp.branch=${liBranch}
group by fcp.mdate, fccr.yield, ftp.IS_RUSH_BACK, ftpa.is_accr_penalty_int, ftpa.penalty_base_type, fpty.TYPE_8, ftp.finprod_id, ftp.mdate, nvl(fp.FINPROD_ABBR,fp.FINPROD_NAME), ftp.FINPROD_TYPE, ftp.FINPROD_TYPE2

select #{finprodType2} finprodType2, sys_datadict_list.item_value finprodTypeName, FIN_PRODUCT.FINPROD_ID finprodId , FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.TRADE_MARKET tradeMarket, nvl(FIN_PRODUCT.FINPROD_ABBR,FIN_PRODUCT.FINPROD_NAME) finprodName, FIN_CASH_PLAN.CASH_TYPE cashType, FIN_TRADE_PRODUCT.VDATE vdate, FIN_TRADE_PRODUCT.MDATE mdate, FIN_TRADE_PRODUCT.CCY ccy, nvl(FIN_PRODUCT_2.FINPROD_NAME,STL_SEC_ACCT_INFO.SEC_ACCT_NAME) chIldName, #{secManageAcctId} secAcctId,
#{bjBranch} bjBranch,
#{liBranch} liBranch,
CASE WHEN FIN_PRODUCT_2.FINPROD_ID IS NOT NULL THEN 1 ELSE 0 END channel, FIN_PRODUCT_ADD.COLLECT_TYPE collectType from FIN_TRADE_PRODUCT left join FIN_CASH_INFO on FIN_TRADE_PRODUCT.FINPROD_ID=FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_2 =
#{CASH_TYPE_2_C01}
#{CASH_TYPE_2_C02}
left join FIN_CASH_PLAN on FIN_CASH_INFO.CASH_ID = FIN_CASH_PLAN.CASH_ID and FIN_TRADE_PRODUCT.MDATE=FIN_CASH_PLAN.MDATE left join FIN_PRODUCT on FIN_TRADE_PRODUCT.FINPROD_ID= FIN_PRODUCT.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO ON STL_SEC_ACCT_INFO.SEC_ACCT_ID = #{secManageAcctId} LEFT JOIN FIN_PRODUCT FIN_PRODUCT_2 ON FIN_PRODUCT_2.FINPROD_ID = #{secManageAcctId} LEFT JOIN FIN_PRODUCT_ADD FIN_PRODUCT_ADD ON FIN_PRODUCT_2.FINPROD_ID=FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN sys_datadict_list on sys_datadict_list.item_code =#{finprodType2} and sys_datadict_list.dict_code=#{PINAN_ASSET_TYPE} where FIN_TRADE_PRODUCT.FINPROD_ID=#{finprodId} and FIN_TRADE_PRODUCT.BRANCH =
#{liBranch}
#{bjBranch}

select DISTINCT fp.FINPROD_MARKET_ID id, fp.finprod_abbr text, fp.FINPROD_ID, fpy.type_8 from FIN_PRODUCT fp inner join FIN_PRODUCT_TYPE fpy on fp.FINPROD_ID = fpy.FINPROD_ID
fp.FINPROD_MARKET_ID = #{initValue}
and (instr(fp.FINPROD_MARKET_ID, #{search}) > 0 or instr(fp.FINPROD_NAME, #{search}) > 0 OR instr(fp.finprod_id, #{search}) > 0 )
and fpy.type_8 in
#{finprodType}
and fpy.type_8 in ('F01','F03','F05','F06')
and fp.PROFIT_TYPE = #{profitType}

select
pp.PORTFOLIO_ID id, pp.PORTFOLIO_NAME text,
sum(decode(prp.REC_TYPE,#{RECE_TYPE_YQWSBJ},nvl(prp.AMOUNT,0),0)) theoryPrin, sum(decode(prp.REC_TYPE,#{RECE_TYPE_YQWSLX},nvl(prp.AMOUNT,0),0)) theoryIntSx, sum(decode(prp.REC_TYPE,#{RECE_TYPE_HBWSLX},nvl(prp.AMOUNT,0),0)) theoryIntHb, sum(decode(prp.REC_TYPE,#{RECE_TYPE_YQWSBJ},nvl(fxinfo.RECE_AMT,0),0)) amountBj, sum(decode(prp.REC_TYPE,#{RECE_TYPE_YQWSLX},nvl(fxinfo.RECE_AMT,0),0)) amountLx, sum(decode(prp.REC_TYPE,#{RECE_TYPE_HBWSLX},nvl(fxinfo.RECE_AMT,0),0)) amountHbWfx, sum(decode(prp.REC_TYPE,#{RECE_TYPE_YQWSBJ},nvl(fxinfo.PENALTY_INT_AMT,0),0)) penaltyIntBj, sum(decode(prp.REC_TYPE,#{RECE_TYPE_YQWSLX},nvl(fxinfo.PENALTY_INT_AMT,0),0)) penaltyIntLx, sum(decode(prp.REC_TYPE,#{RECE_TYPE_HBWSLX},nvl(fxinfo.PENALTY_INT_AMT,0),0)) penaltyIntHbWfx, sum(decode(prp.REC_TYPE,#{RECE_TYPE_YQWSBJ},nvl(actInfo.actPayInt,0),0)) actPenaltyIntBj, sum(decode(prp.REC_TYPE,#{RECE_TYPE_YQWSLX},nvl(actInfo.actPayInt,0),0)) actPenaltyIntLx, sum(decode(prp.REC_TYPE,#{RECE_TYPE_HBWSLX},nvl(actInfo.actPayInt,0),0)) actPenaltyIntHbWfx from PTL_RECE_POSITION prp
left join VW_REPAY_WITHOUT_INT vrwi on prp.BRANCH = vrwi.WITHOUT_BRANCH and prp.FINPROD_ID = vrwi.FINPRODID
left join ( select sum(nvl(PENALTY_INT_AMT,0)) PENALTY_INT_AMT, sum(nvl(RECE_AMT,0)) RECE_AMT, FINPROD_ID, BRANCH, PORTFOLIO_ID from PTL_SEC_RECEIVABLES psr where CDATE = #{sysDate} -1 group by FINPROD_ID,BRANCH,PORTFOLIO_ID ) fxinfo on fxinfo.FINPROD_ID = prp.FINPROD_ID and prp.BRANCH = fxinfo.BRANCH and fxinfo.PORTFOLIO_ID = prp.PORTFOLIO_ID
left join ( select tfpdt.PORTFOLIO_ID, tfpdt.FINPROD_ID, tfpdt.BRANCH, nvl(decode(tfpdt.PS,#{PS_YSKZR},tfpdt.TRADE_AMT*-1,tfpdt.TRADE_AMT),0) actPayInt, tfpdt.SEC_MANAGE_ACCT_ID, tfpdt.CHL_ID from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL paTotal on paTotal.TOTLE_TRADE_ID = tfpdt.TOTLE_TRADE_ID where tfpdt.BUSI_TYPE = #{BUSI_TYPE_YQJY} and tfpdt.TRADE_STATUS = #{TRADE_STATUS_CS} and nvl(tfpdt.IS_CANCEL,#{YN_N}) = #{YN_N} and tfpdt.TRADE_DATE = #{sysDate} ) actInfo on actInfo.FINPROD_ID = prp.FINPROD_ID and prp.BRANCH = actInfo.BRANCH and actInfo.PORTFOLIO_ID = prp.PORTFOLIO_ID and (actInfo.SEC_MANAGE_ACCT_ID = prp.SEC_ACCT_ID or actInfo.CHL_ID = prp.SEC_ACCT_ID) left join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID
pp.INVEST_YESORNO = #{YON_Y}
and (instr(pp.PORTFOLIO_ID, #{search}) > 0 or instr(pp.PORTFOLIO_NAME, #{search}) > 0 )
and pp.PORTFOLIO_ID = #{initValue}
and prp.BRANCH in (
#{bjBranch}
,
#{liBranch}
)
and prp.FINPROD_ID = #{finprodId}
and prp.CDATE = #{sysDate} and prp.SEC_ACCT_ID = #{secAcctId} and prp.HODING_TYPE = #{POSITION_TYPE_SJ}
and pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
group by prp.SEC_ACCT_ID,prp.FINPROD_ID,prp.INV_AIM,prp.PAY_DATE,pp.PORTFOLIO_ID,pp.PORTFOLIO_NAME

select listagg(fcp.cash_id, ',') within group( order by ftp.branch) cashIds from fin_trade_product ftp left join Fin_Cash_Plan fcp on fcp.finprod_id = ftp.finprod_id and fcp.branch = ftp.branch
and ftp.finprod_id =#{finprodId}
and ftp.branch in
${item}

 select listagg(WITHOUT_BRANCH, ',') within
group(
order by WITHOUT_BRANCH) withoutBranch
 from vw_repay_without_int
where FINPRODID = #{finprodId}
  and BRANCH = ${liBranch}

select count(1)
from
(   select
    1
    from
    TRD_FIN_PRODUCT_DEAL_TOTAL total
    where
    total.FINPROD_ID = #{finprodId}
    and total.PORTFOLIO_ID = #{portfolioId}
    and total.TG_BUSI_TYPE in (#{PINAN_BUSINESS_TYPE_YDQZCZR},#{PINAN_BUSINESS_TYPE_YDQZCCXQ})
    and total.TRADE_STATUS =#{TRADE_STATUS_CS}
    and total.IS_CANCEL =#{YON_N}
    and total.TRADE_DATE >= #{transferDate}
    and total.ps = #{PS_MC}
    union all
    select
    1
    from
    WFL_TRD_FIN_PRODUCT_DEAL_TOTAL total
    where
    total.FINPROD_ID = #{finprodId}
    and total.PORTFOLIO_ID = #{portfolioId}
    and total.TG_BUSI_TYPE in (#{PINAN_BUSINESS_TYPE_YDQZCZR},#{PINAN_BUSINESS_TYPE_YDQZCCXQ})
    and total.TRADE_STATUS =#{TRADE_STATUS_CS}
    and total.IS_CANCEL =#{YON_N}
    and total.TRADE_DATE >= #{transferDate}
    and total.ps = #{PS_MC}
)
